import { inject, ref, type Ref } from 'vue'
import { completeSession, levelOf } from './progress'
import { MISSION_KEY, type MissionCtx } from './mission'
import { motivate } from './praise'
import { speak } from './speech'
import { sfx } from './sfx'

/**
 * Shared minigame loop. A session has a fixed number of rounds; every round
 * is generated by `make(index, level)` so each game only describes its task.
 */
export function useGame<T>(id: string, total: number, make: (index: number, level: 1 | 2 | 3) => T) {
  const mission = inject<MissionCtx | null>(MISSION_KEY, null)
  // Missions carry their own rank level; normal games grow from progress.
  const currentLevel = () => mission?.level ?? levelOf(id)
  const level = currentLevel()
  // A mission is a short burst: at most three rounds per challenge.
  const rounds = mission ? Math.min(total, 3) : total
  const index = ref(0)
  const task = ref(make(0, level)) as Ref<T>
  const celebrate = ref(false)
  const finished = ref(false)
  const mistakes = ref(0)
  let locked = false
  let timer = 0

  function finish() {
    finished.value = true
    completeSession(id)
    sfx.win()
    speak(motivate('praise'))
    if (mission) {
      mission.done()
      return
    }
    celebrate.value = true
  }

  function solve() {
    if (locked || finished.value) return
    locked = true
    sfx.correct()
    motivate('praise')
    window.clearTimeout(timer)
    if (index.value + 1 >= rounds) {
      window.setTimeout(finish, 480)
    } else {
      timer = window.setTimeout(() => {
        index.value += 1
        task.value = make(index.value, level)
        locked = false
      }, 520)
    }
  }

  function miss() {
    if (locked || finished.value) return
    mistakes.value += 1
    sfx.wrong()
    motivate('encourage')
  }

  function restart() {
    window.clearTimeout(timer)
    locked = false
    index.value = 0
    mistakes.value = 0
    finished.value = false
    celebrate.value = false
    motivate('cheer')
    task.value = make(0, currentLevel())
  }

  motivate('cheer')

  return {
    id,
    task,
    index,
    total: rounds,
    level,
    celebrate,
    finished,
    mistakes,
    solve,
    miss,
    restart,
  }
}
